STBL_IDX_WD_870MCS = "Shotgun developed in U.S.A.\nAdptiong pump action style and the barrage is possible in spite of the number of the bullets loaded. Strong power at the short distance but diminishing accuracy rate at the long distance."
STBL_IDX_WD_AK47 = "Its design was considering the importance of Close Quarters Combat performance and in many places since it's easy to make and has simple innards. It has high destructibility and also has high recoil relatively which means to have low accuracy rate."
STBL_IDX_WD_COLT = "Hand Gun developed in U.S.A.\nInitial model was devoloped in 1890 and it has been devloped till now.\n Big recoil is the weak point."
STBL_IDX_WD_DESERTEAGLE = "Large handgun developed in Israel.\nDesigned in same production method like the rifle and it's using large caliber ammo so it's called most powerful pistol in the world and it has strong destructive power."
STBL_IDX_WD_DRAGUNOV = "Sniper rifle developed in German. Strong durability.  Accuracy rate is comparatively lower than PSG-1 but it has simple structure and its semi automation method enables rapid firing."
STBL_IDX_WD_FLASHBANG = "The weapon could neutralize the enemy temporarily by loud noise and the light so called 'flash bang'. It's better to disturb the enemy than smoke ball but the effect applies the same for the person who use it so it's important to have the proficiency."
STBL_IDX_WD_K1 = "Submachine gun developed in Korea.\nIt's using 5.56mm rifle bullets and the length is short and good to carry since it's light compared to the K-2 so it's widely used in the special forces troops which requires rapid move or by the soldiers riding in the small spaces like the tank."
STBL_IDX_WD_K2 = "Service rifle made in Korea.\nThe rifle developed in the country which fits to Korean(Asian) figure well and the design was conidered  mountainous terrain. It has high effective range and destructibility due to the highly improved bullets rotation speed."
STBL_IDX_WD_K400 = "Explosive weapon which is damageable with powerful blast and the splinters could neutralize the enemy and the weapon. The weak point is that it's useful in short distance battle rather than long distance enemy by hand throw."
STBL_IDX_WD_M4A1 = "The default chat channel can be changed using F2 and F3.\n\n[F2: Normal Chat, F3: Team Chat]"
STBL_IDX_WD_M7 = "The weapon to suppress the enemy without making any sound. Generally it's equipped with the rifle or used alone."
STBL_IDX_WD_M9 = "The weapon to suppress the enmy without making any sound. Generally it's equipped with the rifle or used alone. Generally it's equipped with the rifle or used alone."
STBL_IDX_WD_MK23 = "Hand Gun developed in German.\nIt was devoloved as requested by SOSCOM in U.S.A and it could attach various option. Compared to the various option it's quite heavy and low destructive power."
STBL_IDX_WD_MP5K = "Submachine gun which is miniature of MP5, it has fast rapid firing speed due to the small size, but the recoil is relatively high. MP5 types are widely used in special forces troops, polices, military from the all over the world."
STBL_IDX_WD_PSG1 = "Sniper rifle developed in German. It was high accuracy rate so it's widely used and supplied for the special forces troops. But due to the semi automation method it has unique manipulation which is difficult to manipulate."
STBL_IDX_WD_SG550 = "Rifle made in Switzerland.\n It is light and has the high accuracy rate among the mass produced automatic rifles since it's designed considering mountainous terrain."
STBL_IDX_WD_SMOKE = "The weapon could dim the enemy's view to confuse them so called 'smoke ball'. Depending on the type it's used to criple the enemy and in Point Blank it's used as the strategic weapon to blur the enemy's view."
STBL_IDX_WD_SPETRE = "SMG is designed to response rapidly at the certain situation and and it has fast rapid firing speed and stable shooting from the perpendicular grip. But it's heavy for the size so not so good to carry along"
STBL_IDX_WD_SSG69 = "Sniper rifle developed in Austria.\nAdopting bolt action style and the accuracy rate is better than PSG-1. Disabled rapid firing is one of the disadvantage but a lot of  the special forces troop is using it."
